CREATE TABLE "requirement_ideas" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(20) NOT NULL DEFAULT acp_generate_public_code(),
  "project_id" bigint NOT NULL,
  "title" text NOT NULL,
  "detail" text NOT NULL DEFAULT '',
  "source" text,
  "status" text NOT NULL DEFAULT 'active',
  "created_by" bigint NOT NULL,
  "created_at" text NOT NULL,
  "updated_at" text NOT NULL,
  CONSTRAINT "ck_requirement_ideas_code" CHECK ("code" ~ '^[0-9A-HJKMNP-TV-Z]{20}$'),
  CONSTRAINT "ck_requirement_ideas_status" CHECK ("status" IN ('active', 'archived'))
);
--> statement-breakpoint
CREATE TABLE "requirement_topics" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(20) NOT NULL DEFAULT acp_generate_public_code(),
  "project_id" bigint NOT NULL,
  "title" text NOT NULL,
  "problem_statement" text NOT NULL DEFAULT '',
  "goal" text NOT NULL DEFAULT '',
  "status" text NOT NULL DEFAULT 'open',
  "created_by" bigint NOT NULL,
  "created_at" text NOT NULL,
  "updated_at" text NOT NULL,
  CONSTRAINT "ck_requirement_topics_code" CHECK ("code" ~ '^[0-9A-HJKMNP-TV-Z]{20}$'),
  CONSTRAINT "ck_requirement_topics_status" CHECK ("status" IN ('open', 'decided', 'reopened', 'archived'))
);
--> statement-breakpoint
CREATE TABLE "requirement_topic_ideas" (
  "topic_id" bigint NOT NULL,
  "idea_id" bigint NOT NULL,
  "created_at" text NOT NULL,
  PRIMARY KEY ("topic_id", "idea_id")
);
--> statement-breakpoint
CREATE TABLE "requirement_topic_entries" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(20) NOT NULL DEFAULT acp_generate_public_code(),
  "topic_id" bigint NOT NULL,
  "entry_type" text NOT NULL,
  "content" text NOT NULL,
  "rationale" text,
  "supersedes_entry_id" bigint,
  "source_entity_type" text,
  "source_entity_code" varchar(20),
  "author_principal_id" bigint NOT NULL,
  "created_at" text NOT NULL,
  CONSTRAINT "ck_requirement_topic_entries_code" CHECK ("code" ~ '^[0-9A-HJKMNP-TV-Z]{20}$'),
  CONSTRAINT "ck_requirement_topic_entries_type" CHECK ("entry_type" IN ('comment', 'alternative', 'feedback', 'decision')),
  CONSTRAINT "ck_requirement_topic_entries_source_code" CHECK ("source_entity_code" IS NULL OR "source_entity_code" ~ '^[0-9A-HJKMNP-TV-Z]{20}$')
);
--> statement-breakpoint
CREATE TABLE "requirement_topic_documents" (
  "topic_id" bigint NOT NULL,
  "document_id" bigint NOT NULL,
  "created_at" text NOT NULL,
  PRIMARY KEY ("topic_id", "document_id")
);
--> statement-breakpoint
CREATE TABLE "requirement_document_reviews" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(20) NOT NULL DEFAULT acp_generate_public_code(),
  "document_revision_id" bigint NOT NULL,
  "status" text NOT NULL DEFAULT 'open',
  "conclusion" text,
  "requested_by" bigint NOT NULL,
  "opened_at" text NOT NULL,
  "closed_by" bigint,
  "closed_at" text,
  CONSTRAINT "ck_requirement_document_reviews_code" CHECK ("code" ~ '^[0-9A-HJKMNP-TV-Z]{20}$'),
  CONSTRAINT "ck_requirement_document_reviews_status" CHECK ("status" IN ('open', 'closed', 'cancelled')),
  CONSTRAINT "ck_requirement_document_reviews_conclusion" CHECK ("conclusion" IS NULL OR "conclusion" IN ('passed', 'changes_requested', 'no_consensus'))
);
--> statement-breakpoint
CREATE TABLE "requirement_document_review_votes" (
  "review_id" bigint NOT NULL,
  "principal_id" bigint NOT NULL,
  "vote" text NOT NULL,
  "comment" text NOT NULL DEFAULT '',
  "responded_at" text NOT NULL,
  PRIMARY KEY ("review_id", "principal_id"),
  CONSTRAINT "ck_requirement_document_review_votes_vote" CHECK ("vote" IN ('support', 'changes_requested', 'abstain'))
);
